/*
 * prog55_connected_components.c
 *
 * Re‑implementation of the original program whose behaviour was observed
 * in the supplied binary.  The program reads an undirected graph with
 * at most 8 vertices (numbered 0‑7) from the command line, computes its
 * connected components and prints them.
 *
 * Expected command line format:
 *
 *   prog55_connected_components v0 w0 v1 w1 ... vk wk
 *
 * where each pair (vi, wi) describes an undirected edge.  The number of
 * arguments after the program name must be even; otherwise the program
 * prints "INVALID_INPUT" and exits with status 1.  All vertex numbers must
 * be in the range [0,7]; otherwise the same error is reported.
 *
 * Output format (one line per component):
 *
 *   <component_number>: {v_a,v_b,...,v_z}
 *
 * Vertices are listed in the order they are discovered by a breadth‑first
 * search starting from the smallest not‑yet‑visited vertex.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8                     /* maximum number of vertices */

int main(int argc, char **argv)
{
    /* -----------------------------------------------------------------
     *  Input validation
     * ----------------------------------------------------------------- */
    if ((argc - 1) % 2 != 0) {          /* need an even number of numbers */
        puts("INVALID_INPUT");
        return 1;
    }

    /* -----------------------------------------------------------------
     *  Build adjacency matrix
     * ----------------------------------------------------------------- */
    int adj[MAXV][MAXV] = { {0} };
    int edge_cnt = (argc - 1) / 2;

    for (int i = 0; i < edge_cnt; ++i) {
        /* arguments are: argv[1] argv[2] argv[3] argv[4] ...   */
        int a = (int)strtol(argv[2 * i + 1], NULL, 10);
        int b = (int)strtol(argv[2 * i + 2], NULL, 10);

        if (a < 0 || a >= MAXV || b < 0 || b >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }

        adj[a][b] = 1;
        adj[b][a] = 1;                  /* undirected graph */
    }

    /* -----------------------------------------------------------------
     *  Find and print connected components (BFS)
     * ----------------------------------------------------------------- */
    int visited[MAXV] = {0};
    int queue[MAXV];
    int component_no = 0;

    for (int start = 0; start < MAXV; ++start) {
        if (visited[start])
            continue;                  /* already part of a previous component */

        ++component_no;

        /* BFS initialisation */
        int qhead = 0, qtail = 0;
        queue[qtail++] = start;
        visited[start] = 1;

        /* store vertices of the current component in discovery order */
        int comp_vertices[MAXV];
        int comp_sz = 0;

        while (qhead < qtail) {
            int v = queue[qhead++];
            comp_vertices[comp_sz++] = v;

            for (int u = 0; u < MAXV; ++u) {
                if (adj[v][u] && !visited[u]) {
                    visited[u] = 1;
                    queue[qtail++] = u;
                }
            }
        }

        /* -----------------------------------------------------------------
         *  Output the component
         * ----------------------------------------------------------------- */
        printf("%d:", component_no);
        printf(" {");
        for (int i = 0; i < comp_sz; ++i) {
            if (i > 0)
                putchar(',');
            printf("%d", comp_vertices[i]);
        }
        putchar('}');
        putchar('\n');
    }

    return 0;
}
